/* ── Particles ──────────────────────────────────────────────────────────── */
const particleGroup = new THREE.Group(); scene.add(particleGroup);
const sphereGeo = new THREE.SphereGeometry(0.11, 20, 16);
const texPlusW = glyphTex('+', '#ffffff');
const texMinusW = glyphTex('\u2212', '#ffffff');

const XL = -0.50, XR = 0.50, YMIN = 0.48, YMAX = 1.70, ZR = 0.32;
let particles = [];

function greenBall(mats) {
  const g = new THREE.Group();
  const m = matIonBase.clone(); mats.push(m);
  const rm = matRimBase.clone(); mats.push(rm);
  g.add(new THREE.Mesh(sphereGeo, m));
  const rim = new THREE.Mesh(sphereGeo, rm); rim.scale.setScalar(1.14); g.add(rim);
  return g;
}
function makeArrow(dirX, L, mats) {
  const g = new THREE.Group();
  const am = matArrow.clone(); mats.push(am);
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, L - 0.12, 8), am);
  shaft.rotation.z = Math.PI / 2;
  shaft.position.x = dirX * (0.17 + (L - 0.12) / 2);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.052, 0.13, 12), am);
  head.rotation.z = dirX > 0 ? -Math.PI / 2 : Math.PI / 2;
  head.position.x = dirX * (0.17 + L - 0.06);
  g.add(shaft, head);
  return g;
}
function rnd(a, b) { return a + Math.random() * (b - a); }

function addNeutral() {
  const mats = [];
  const g = new THREE.Group();
  const a = greenBall(mats); a.position.x = -0.08;
  const b = greenBall(mats); b.position.x = 0.08;
  g.add(a, b);
  g.position.set(rnd(XL - 0.25, XR + 0.25), rnd(YMIN, YMAX), rnd(-ZR, ZR));
  g.rotation.set(rnd(0, 3), rnd(0, 3), rnd(0, 3));
  g.scale.setScalar(0.01);
  particleGroup.add(g);
  particles.push({
    type: 'neutral', obj: g, mats, age: 0,
    vel: new THREE.Vector3(rnd(-0.1, 0.1), rnd(-0.06, 0.06), rnd(-0.05, 0.05)),
    spin: rnd(-0.9, 0.9)
  });
}
function addIon(sign) {
  const mats = [];
  const g = greenBall(mats);
  const spr = new THREE.Sprite(new THREE.SpriteMaterial({
    map: sign > 0 ? texPlusW : texMinusW, transparent: true, depthTest: false, depthWrite: false
  }));
  mats.push(spr.material);
  spr.scale.set(0.15, 0.15, 1); spr.renderOrder = 9; g.add(spr);
  const dir = sign > 0 ? -1 : 1;                    // cations → '−' plate (left)
  g.add(makeArrow(dir, 0.58, mats));
  g.position.set(rnd(XL + 0.08, XR - 0.08), rnd(YMIN, YMAX), rnd(-ZR, ZR));
  g.scale.setScalar(0.01);
  particleGroup.add(g);
  particles.push({ type: 'ion', obj: g, mats, age: 0, dir, sign, speed: rnd(0.22, 0.34) });
}
function clearParticles() {
  for (const p of particles) {
    particleGroup.remove(p.obj);
    p.obj.traverse(o => { if (o.isSprite) o.material.dispose(); });
    p.mats.forEach(m => m.dispose && m.dispose());
  }
  particles = [];
}

/* ── State ──────────────────────────────────────────────────────────────── */
const SOL = {
  ethanol: { line1: 'ethanol', line2: 'No conductivity', alpha: 0.0, nNeutral: 5, nIon: 0 },
  kcl: { line1: 'KCl', line2: 'High conductivity', alpha: 1.0, nNeutral: 0, nIon: 6 },
  acetic: { line1: 'acetic acid solution', line2: 'Low conductivity', alpha: 0.12, nNeutral: 3, nIon: 2 }
};
let current = 'ethanol';
let conc = 0.5;
let running = true;
let lastCounts = { n: -1, i: -1 };

function counts() {
  const s = SOL[current];
  return { n: Math.round(s.nNeutral * conc * 2), i: 2 * Math.round(s.nIon * conc) };
}
function rebuildIfNeeded(force) {
  const c = counts();
  if (!force && c.n === lastCounts.n && c.i === lastCounts.i) return;
  lastCounts = c;
  clearParticles();
  for (let k = 0; k < c.n; k++) addNeutral();
  for (let k = 0; k < c.i; k++) addIon(k % 2 === 0 ? 1 : -1);
}

const capName = addLabel('ethanol', new THREE.Vector3(0, -0.45, 0), { fontSize: '16px' });
const capCond = addLabel('No conductivity', new THREE.Vector3(0, -0.88, 0), { fontSize: '16px' });

function setBrightness(b) {
  const vis = b <= 0 ? 0 : Math.pow(Math.min(1, b), 0.6);
  matFilament.emissiveIntensity = vis * 2.4;
  matFilament.color.setHex(vis > 0.03 ? 0xF0A030 : 0x8C8C8C);
  matBulbGlass.emissiveIntensity = vis * 0.35;
  halo.material.opacity = 0.85 * vis;
  const hs = 1.5 + 1.6 * vis;
  halo.scale.set(hs, hs, 1);
  bulbLight.intensity = vis * 2.2;
  return vis;
}

function refreshUI(vis) {
  document.getElementById('concVal').textContent = conc.toFixed(2);
  document.getElementById('conc').value = conc;
  document.getElementById('alphaVal').textContent = SOL[current].alpha.toFixed(2);
  document.getElementById('brVal').textContent = Math.round(vis * 100) + '%';
  const st = document.getElementById('bulbState');
  st.textContent = vis < 0.02 ? 'bulb dark — no free ions' : (vis < 0.4 ? 'bulb dim — few ions' : 'bulb bright — many ions');
  document.getElementById('btnEth').classList.toggle('active', current === 'ethanol');
  document.getElementById('btnKCl').classList.toggle('active', current === 'kcl');
  document.getElementById('btnAce').classList.toggle('active', current === 'acetic');
}

function applyState(force) {
  rebuildIfNeeded(force);
  const vis = setBrightness(SOL[current].alpha * conc);
  capName.div.innerHTML = SOL[current].line1;
  capCond.div.innerHTML = SOL[current].line2;
  refreshUI(vis);
}

/* ── Camera (after geometry) ────────────────────────────────────────────── */
setCameraView({
