controls.minAzimuthAngle = THREE.MathUtils.degToRad(-5);
controls.maxAzimuthAngle = THREE.MathUtils.degToRad(75);

/* ── Controls wiring ────────────────────────────────────────────────────── */
document.getElementById('btnEth').addEventListener('click', () => { current = 'ethanol'; applyState(true); });
document.getElementById('btnKCl').addEventListener('click', () => { current = 'kcl'; applyState(true); });
document.getElementById('btnAce').addEventListener('click', () => { current = 'acetic'; applyState(true); });

const runBtn = document.getElementById('btnRun');
runBtn.classList.add('active');
runBtn.addEventListener('click', () => {
  running = !running;
  runBtn.textContent = running ? '⏸ Pause current' : '▶ Run current';
  runBtn.classList.toggle('active', running);
});

document.getElementById('conc').addEventListener('input', (e) => {
  concTween = null;
  conc = parseFloat(e.target.value);
  applyState(false);
});

/* ── Demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'Ethanol — no conductivity', sol: 'ethanol', c: 0.5,
    text: 'Ethanol dissolves as intact neutral molecules (green dumbbells) that only jiggle randomly. With no free charges to move between the plates, the circuit is open and the bulb stays completely dark.'
  },
  {
    title: 'KCl — high conductivity', sol: 'kcl', c: 0.5,
    text: 'KCl dissociates completely: every formula unit becomes a K⁺ and a Cl⁻. The K⁺ ions stream left toward the negative plate and Cl⁻ ions right toward the positive plate, and the dense two-way ion traffic lights the bulb brightly.'
  },
  {
    title: 'Acetic acid — low conductivity', sol: 'acetic', c: 0.5,
    text: 'Acetic acid only partially ionizes; most of the solute stays as neutral molecules and just a few ions migrate. Far fewer charge carriers means only a dim glow.'
  },
  {
    title: 'Dilute the strong electrolyte', sol: 'kcl', c: 0.1,
    text: 'Drop the KCl concentration toward zero and watch the ions thin out and the bulb fade — conductivity tracks the number of ions, not just their identity.'
  },
  {
    title: 'Concentrate the weak electrolyte', sol: 'acetic', c: 1.0,
    text: 'Raising the acetic acid concentration adds ions and brightens the bulb, but it never matches KCl at the same concentration because only a small fraction of molecules ionize.'
  }
];
let stepIdx = 0;
let concTween = null;

function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  current = s.sol;
  concTween = { from: conc, to: s.c, t: 0, dur: 0.7 };
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.text;
  applyState(true);
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── Particle animation loop ────────────────────────────────────────────── */
function stepParticles(dt) {
  for (const p of particles) {
    p.age += dt;
    let fade = Math.min(1, p.age / 0.35);
    if (p.type === 'ion') {
      if (running) {
        p.obj.position.x += p.dir * p.speed * dt;
        const end = p.dir < 0 ? XL : XR;
        if ((p.dir < 0 && p.obj.position.x <= end) || (p.dir > 0 && p.obj.position.x >= end)) {
          p.obj.position.set(p.dir < 0 ? XR : XL, rnd(YMIN, YMAX), rnd(-ZR, ZR));
        }
      }
      const dEnd = Math.abs(p.obj.position.x - (p.dir < 0 ? XL : XR));
      const dStart = Math.abs(p.obj.position.x - (p.dir < 0 ? XR : XL));
      fade = Math.min(fade, Math.min(1, dEnd / 0.16), Math.min(1, dStart / 0.16));
    } else {
      if (running) {
        p.vel.x += (Math.random() - 0.5) * 0.9 * dt;
        p.vel.y += (Math.random() - 0.5) * 0.7 * dt;
        p.vel.z += (Math.random() - 0.5) * 0.6 * dt;
        p.vel.multiplyScalar(0.96);
        p.obj.position.addScaledVector(p.vel, dt);
        p.obj.rotation.z += p.spin * dt;
        p.obj.rotation.y += p.spin * 0.6 * dt;
        const q = p.obj.position;
        if (q.x < XL - 0.3) { q.x = XL - 0.3; p.vel.x *= -1; }
        if (q.x > XR + 0.3) { q.x = XR + 0.3; p.vel.x *= -1; }
        if (q.y < YMIN) { q.y = YMIN; p.vel.y *= -1; }
        if (q.y > YMAX) { q.y = YMAX; p.vel.y *= -1; }
        if (q.z < -ZR - 0.15) { q.z = -ZR - 0.15; p.vel.z *= -1; }
        if (q.z > ZR + 0.15) { q.z = ZR + 0.15; p.vel.z *= -1; }
      }
    }
    const sc = 0.35 + 0.65 * fade;
    p.obj.scale.setScalar(sc);
    for (const m of p.mats) { m.transparent = true; m.opacity = fade; }
  }
}

function tick() {
  requestAnimationFrame(tick);
  const dt = Math.min(0.05, _clock.getDelta());
  if (concTween) {
    concTween.t += dt;
    const u = Math.min(1, concTween.t / concTween.dur);
    const e = u * u * (3 - 2 * u);
    conc = Math.round((concTween.from + (concTween.to - concTween.from) * e) / 0.05) * 0.05;
    applyState(false);
    if (u >= 1) { conc = concTween.to; concTween = null; applyState(false); }
  }
  stepParticles(dt);
}

/* ── Init ───────────────────────────────────────────────────────────────── */
applyState(true);
document.getElementById('stepTitle').textContent = '1. ' + STEPS[0].title;
document.getElementById('stepText').textContent = STEPS[0].text;
tick();
